<script>const paymentSelect=document.getElementById('business-payment-method');const paymentCards=document.querySelectorAll('.payment-method-card');function showPaymentMethod(){paymentCards.forEach((card)=>card.classList.toggle('d-none',card.dataset.paymentMethod!==paymentSelect.value));}paymentSelect.addEventListener('change',showPaymentMethod);showPaymentMethod();</script>
